/**
 * POST /api/webhooks/stripe
 *
 * Handles Stripe checkout.session.completed:
 *  1. Creates Order with status PAID + erpSyncStatus=pending_erp_sync
 *  2. Tries to sync to ERP immediately via POST /api/orders
 *  3a. Success → status=PROCESSING, store ESH number + invoice, send confirmation email WITH invoice PDF
 *  3b. Failure → keep status PAID, erpSyncStatus=pending_erp_sync, send ack email without invoice
 *  4. Deducts stock, clears cart
 *
 * GDPR: logs use order IDs only — no customer PII in log output.
 * § 28 ZDPH: invoice is generated by ERP immediately upon payment receipt.
 */

import { NextRequest, NextResponse } from 'next/server'
import { stripe } from '@/lib/stripe'
import { db } from '@/lib/db'
import { sendEmail } from '@/lib/email/send'
import { OrderConfirmationWithInvoice, OrderConfirmationAck } from '@/lib/email/templates/OrderConfirmation'
import { NewOrderNotification } from '@/lib/email/templates/NewOrderNotification'
import { getErpConfig, syncOrderToErp } from '@/lib/erp'
import type Stripe from 'stripe'

export const dynamic = 'force-dynamic'

// Stripe webhooks must consume raw body
export async function POST(req: NextRequest) {
  const body      = await req.text()
  const signature = req.headers.get('stripe-signature')

  if (!signature || !process.env.STRIPE_WEBHOOK_SECRET) {
    return NextResponse.json({ error: 'Missing signature' }, { status: 400 })
  }

  let event: Stripe.Event
  try {
    event = stripe.webhooks.constructEvent(body, signature, process.env.STRIPE_WEBHOOK_SECRET)
  } catch (err: any) {
    return NextResponse.json({ error: `Webhook Error: ${err.message}` }, { status: 400 })
  }

  if (event.type !== 'checkout.session.completed') {
    return NextResponse.json({ received: true })
  }

  const session      = event.data.object as Stripe.Checkout.Session
  const userId       = session.metadata?.userId
  const itemsRaw     = session.metadata?.items
  const deliveryType = (session.metadata?.deliveryType ?? 'COURIER') as 'COURIER' | 'PICKUP_IN_STORE'
  const addressId    = session.metadata?.addressId || null

  if (!userId || !itemsRaw) return NextResponse.json({ received: true })

  // ── Resolve order items ─────────────────────────────────────────────────────
  const rawItems: { v: string; q: number }[] = JSON.parse(itemsRaw)
  const variants = await db.productVariant.findMany({
    where: { id: { in: rawItems.map(i => i.v) } },
    include: { product: true },
  })
  const variantMap = new Map(variants.map(v => [v.id, v]))

  const items = rawItems.map(i => {
    const variant = variantMap.get(i.v)
    return {
      variantId:    i.v,
      productId:    variant?.productId ?? '',
      productName:  variant?.product?.name ?? 'Product',
      variantLabel: variant?.name ?? '',
      quantity:     i.q,
      unitPrice:    Math.round(Number(variant?.price ?? 0) * 100), // haléře
      erpProductId: variant?.erpProductId ?? null,
      variantValue: variant?.variantValue ?? null,
      variantUnit:  variant?.variantUnit ?? null,
    }
  })

  const totalAmount    = session.amount_total ?? 0
  const shippingAmount = session.shipping_cost?.amount_total ?? 0
  const subtotalAmount = totalAmount - shippingAmount

  // ── Idempotency check ──────────────────────────────────────────────────────
  // The success page may have created the order first (as PAID, pending_erp_sync).
  // If fully synced → nothing to do. If not yet synced → use the existing order
  // and proceed with ERP sync (skip creation).
  const existingOrder = await db.order.findUnique({
    where:   { stripeSessionId: session.id },
    include: { items: true, address: true },
  })

  if (existingOrder?.erpSyncStatus === 'synced') {
    console.log(`[Stripe] Already fully processed — skipping, orderId=${existingOrder.id}`)
    return NextResponse.json({ received: true })
  }

  // ── Create order (or reuse existing from success-page fallback) ─────────────
  let order: any
  if (existingOrder) {
    console.log(`[Stripe] Order created by success page, proceeding with ERP sync, orderId=${existingOrder.id}`)
    order = existingOrder
  } else {
    order = await db.order.create({
      data: {
        userId,
        addressId: addressId || null,
        stripeSessionId:       session.id,
        stripePaymentIntentId: typeof session.payment_intent === 'string' ? session.payment_intent : null,
        status:          'PAID',
        erpSyncStatus:   'pending_erp_sync',
        deliveryType,
        currency:        (session.currency ?? 'czk').toUpperCase(),
        totalAmount,
        subtotalAmount,
        shippingAmount,
        items: {
          create: items.map(item => ({
            productId:    item.productId,
            variantId:    item.variantId,
            productName:  item.productName,
            variantLabel: item.variantLabel,
            quantity:     item.quantity,
            unitPrice:    item.unitPrice,
          })),
        },
      },
      include: { items: true, address: true },
    })
    console.log(`[Stripe] Order created orderId=${order.id}`)
  }

  // ── Load user for email + ERP sync ──────────────────────────────────────────
  const user = await db.user.findUnique({
    where:  { id: userId },
    select: { id: true, name: true, email: true, phone: true },
  })

  // Prefer address already loaded with the order; fallback to DB lookup
  let addr: { fullName: string; line1: string; line2?: string | null; city: string; postalCode: string; country: string } | null =
    order.address ?? null
  if (!addr && addressId) {
    addr = await db.address.findUnique({ where: { id: addressId } })
  }

  // ── Try ERP sync (Phase 1, steps 3-5) ──────────────────────────────────────
  let erpSynced = false
  try {
    const erpConfig = await getErpConfig()
    if (!erpConfig) {
      console.warn(`[ERP] Not configured — skipping sync for orderId=${order.id}`)
    } else {
      // Build address string for ERP
      const streetLine = addr
        ? [addr.fullName, addr.line1, addr.line2].filter(Boolean).join(', ')
        : 'Neuvedena'
      const cityLine   = addr?.city       || 'Neuvedeno'
      const zipLine    = addr?.postalCode || '00000'
      const country    = addr?.country   || 'CZ'

      // Convert haléře → Kč (CZK integer from Stripe / 100 = Kč)
      const totalCzk    = totalAmount / 100
      const subtotalCzk = subtotalAmount / 100

      const erpItems = items.map(item => {
        // Convert e-shop unitPrice (haléře) to CZK excl. VAT
        const unitPriceKc = item.unitPrice / 100                    // Kč with VAT
        const unitPriceExclVat = Math.round(unitPriceKc / 1.21 * 100) / 100
        const erpQty   = item.variantValue ? item.quantity * item.variantValue : item.quantity
        const erpName  = item.variantLabel ? `${item.productName} — ${item.variantLabel}` : item.productName
        return {
          sku:          item.erpProductId ?? undefined,
          name:         erpName,
          quantity:     erpQty,
          unit:         item.variantUnit ?? 'ks',
          unitPriceCzk: unitPriceExclVat,
          vatRate:      21,
        }
      })

      const paymentRef = typeof session.payment_intent === 'string'
        ? session.payment_intent
        : session.id

      const syncResult = await syncOrderToErp({
        eshopOrderId:     order.id,    // cuid — UUID-like, used as idempotency key
        items:            erpItems,
        customer: {
          name:  user?.name  || user?.email || 'Zákazník',
          email: user?.email || '',
          address: {
            street:  streetLine,
            city:    cityLine,
            zip:     zipLine,
            country,
          },
        },
        totalCzk,
        paymentReference: paymentRef,
        paidAt:           new Date().toISOString(),
      }, erpConfig)

      // Update order with ERP data → status PROCESSING
      order = await db.order.update({
        where: { id: order.id },
        data: {
          status:           'PROCESSING',
          erpSyncStatus:    'synced',
          erpOrderNumber:   syncResult.erpOrderNumber,
          invoiceNumber:    syncResult.invoiceNumber,
          invoiceUrl:       syncResult.invoicePdfUrl,
          invoicePdfBase64: syncResult.invoicePdfBase64,
          erpSyncAttempts:  1,
        },
        include: { items: true, address: true },
      })

      // Log sync attempt (success)
      await db.erpSyncAttempt.create({
        data: { orderId: order.id, success: true },
      })

      console.log(`[ERP] Sync success orderId=${order.id} erpOrderNumber=${syncResult.erpOrderNumber}`)
      erpSynced = true
    }
  } catch (erpErr: any) {
    // ERP unreachable — log attempt, keep pending_erp_sync
    console.error(`[ERP] Sync failed for orderId=${order.id}:`, erpErr?.message)
    await db.order.update({
      where: { id: order.id },
      data: {
        erpSyncAttempts:  1,
        erpSyncLastError: erpErr?.message ?? 'Unknown error',
      },
    })
    await db.erpSyncAttempt.create({
      data: { orderId: order.id, success: false, error: erpErr?.message },
    })
  }

  // ── Send customer email ─────────────────────────────────────────────────────
  if (user?.email) {
    try {
      const firstName    = user.name?.split(' ')[0] ?? 'there'
      const shippingAddr = addr
        ? { fullName: addr.fullName, line1: addr.line1, city: addr.city, postalCode: addr.postalCode, country: addr.country }
        : undefined

      if (erpSynced && order.erpOrderNumber) {
        // Mail #1: order confirmed with ERP number + invoice PDF attached (§ 28 ZDPH)
        await sendEmail({
          to:          user.email,
          subject:     `Potvrzení objednávky ${order.erpOrderNumber} — Weedej`,
          react:       OrderConfirmationWithInvoice({
            name:           firstName,
            orderNumber:    order.erpOrderNumber!,
            items:          items.map(i => ({ productName: i.productName, variantLabel: i.variantLabel, quantity: i.quantity, unitPrice: i.unitPrice })),
            subtotalAmount,
            shippingAmount,
            totalAmount,
            deliveryType,
            shippingAddress:  shippingAddr,
            invoiceNumber:    order.invoiceNumber ?? undefined,
          }),
          // Attach invoice PDF if available (§ 28 ZDPH — required in mail #1)
          attachments: order.invoicePdfBase64
            ? [{
                filename:    `faktura-${order.invoiceNumber ?? order.erpOrderNumber}.pdf`,
                content:     order.invoicePdfBase64,
                contentType: 'application/pdf',
                encoding:    'base64',
              }]
            : [],
        })
      } else {
        // ERP unavailable — send acknowledgement without ERP number/invoice
        await sendEmail({
          to:      user.email,
          subject: 'Přijali jsme vaši objednávku — Weedej',
          react:   OrderConfirmationAck({
            name:            firstName,
            internalOrderId: order.id,
            items:           items.map(i => ({ productName: i.productName, variantLabel: i.variantLabel, quantity: i.quantity, unitPrice: i.unitPrice })),
            subtotalAmount,
            shippingAmount,
            totalAmount,
            deliveryType,
            shippingAddress: shippingAddr,
          }),
        })
      }
    } catch (emailErr) {
      console.error(`[Email] Failed for orderId=${order.id}:`, (emailErr as any)?.message)
    }
  }

  // ── Admin notification ──────────────────────────────────────────────────────
  try {
    const adminEmailSetting = await db.setting.findUnique({ where: { key: 'orderNotificationEmail' } })
    const adminEmail        = adminEmailSetting?.value ?? process.env.ADMIN_ORDER_EMAIL
    if (adminEmail) {
      await sendEmail({
        to:      adminEmail,
        subject: `Nová objednávka ${order.erpOrderNumber ?? order.id.slice(-8).toUpperCase()} — Weedej`,
        react:   NewOrderNotification({
          orderNumber:   order.erpOrderNumber ?? order.id,
          customerName:  user?.name ?? user?.email ?? 'Unknown',
          customerEmail: user?.email ?? '',
          items:         items.map(i => ({ productName: i.productName, variantLabel: i.variantLabel, quantity: i.quantity, unitPrice: i.unitPrice })),
          subtotalAmount,
          shippingAmount,
          totalAmount,
          deliveryType,
          shippingAddress: addr
            ? { fullName: addr.fullName, line1: addr.line1, city: addr.city, postalCode: addr.postalCode, country: addr.country }
            : undefined,
        }),
      })
    }
  } catch (adminEmailErr) {
    console.error(`[AdminEmail] Failed for orderId=${order.id}:`, (adminEmailErr as any)?.message)
  }

  // ── Deduct stock ────────────────────────────────────────────────────────────
  for (const item of items) {
    try {
      await db.productVariant.update({
        where: { id: item.variantId },
        data:  { stock: { decrement: item.quantity } },
      })
      await db.stockMovement.create({
        data: {
          variantId: item.variantId,
          type:      'RESERVED',
          quantity:  item.quantity,
          orderId:   order.id,
          reason:    'Order paid',
        },
      })
    } catch (stockErr) {
      console.error(`[Stock] Error for variantId=${item.variantId} orderId=${order.id}:`, (stockErr as any)?.message)
    }
  }

  // ── Clear cart ──────────────────────────────────────────────────────────────
  try {
    await db.cartItem.deleteMany({ where: { cart: { userId } } })
  } catch {}

  return NextResponse.json({ received: true })
}
